package hub

import (
	webassets "github.com/0xikarus/vmbox-service/internal/controller/web"
	"github.com/0xikarus/vmbox-service/internal/standalone"
	"io"
	"net/http"
	"strings"
)

func (s *Server) page(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	if _, ok := s.authorized(r); !ok {
		_, _ = io.WriteString(w, standalone.Page("Hub login", `<h1>vbox Hub</h1><p>Unlock this host’s boxes.</p><form id="login"><div class="field"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password"></div><div class="form-actions"><button class="primary">Unlock</button></div><p id="error" role="status"></p></form><script>document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const r=await fetch('/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:document.querySelector('#password').value})});if(r.ok)location.reload();else document.querySelector('#error').textContent=await r.text()}</script>`))
		return
	}
	picker, _ := webassets.ChatControls.ReadFile("model-picker.js")
	_, _ = io.WriteString(w, standalone.Page("Hub", strings.Replace(hubPage, "<script>", "<script>"+string(picker)+"</script><script>", 1)))
}
func (s *Server) passwordPage(w http.ResponseWriter, r *http.Request) {
	if _, ok := s.authorized(r); !ok {
		http.Redirect(w, r, "/", 303)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_, _ = io.WriteString(w, standalone.Page("Hub password", `<h1>Change hub password</h1><p>The old password is required. Other sessions and viewers will be signed out.</p><form id="password-form"><div class="field"><label>Old password<input name="old" type="password" autocomplete="current-password"></label><label>New password<input name="new" type="password" autocomplete="new-password"></label></div><div class="form-actions"><button class="primary">Save password</button><a href="/">Hub</a></div><p id="result" role="status"></p></form><script>document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,r=await fetch('/auth/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({oldPassword:f.elements.old.value,password:f.elements.new.value})});document.querySelector('#result').textContent=r.ok?'Password changed':await r.text();if(r.ok)f.reset()}</script>`))
}

const hubPage = `<style>
.hub{max-width:1280px;margin:auto;padding:24px}.hub h1{font-size:26px}.hub header,.hub-heading{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.hub .spacer{flex:1}.hub #capacity{color:var(--vb-ink-soft);margin:12px 0 24px}.hub-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:16px}.hub-card,.hub details{border:1px solid var(--vb-line);border-radius:var(--r-surface);padding:20px;background:var(--vb-surface)}.hub-card h2{margin:0 0 6px}.hub-card .reason{color:var(--vb-ink-soft);min-height:24px;font-size:13px}.hub-card .actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.hub .forms{align-items:start;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:16px;margin-top:24px}.hub label{display:flex;flex-direction:column;gap:5px;margin-bottom:10px;font-size:13px}.hub label.check{flex-direction:row;align-items:center}.hub textarea{min-height:80px}.hub pre{white-space:pre-wrap;overflow-wrap:anywhere}.hub summary{font-weight:650;cursor:pointer}.hub .state{font-size:12px;background:var(--vb-surface-2);padding:4px 8px;border-radius:30px}.hub .error{color:var(--vb-danger-text)}.hub select[multiple]{min-height:80px}.hub nav{display:flex;gap:12px;align-items:center}.hub nav button{white-space:nowrap;padding:8px 12px}.hub [hidden]{display:none!important}.hub .profile-row{display:flex;gap:10px;align-items:center;margin:12px 0;overflow-wrap:anywhere}.hub .profile-row span{flex:1}.hub input[type=checkbox]{appearance:auto;width:18px;height:18px;padding:0;flex:none;accent-color:var(--vb-ink)}
</style><main class="hub">
<header><a class="brand" href="/"><img class="brand-logo brand-logo-on-light" src="/vbox-logo.png" alt="vbox"><img class="brand-logo brand-logo-on-dark" src="/vbox-logo-dark.png" alt="vbox"><span>Hub</span></a><span class="spacer"></span><nav><a href="/password">Change password</a><button id="hub-logout">Sign out</button></nav></header>
<div class="hub-heading"><h1>Your boxes</h1><span class="spacer"></span><a href="#create">Create box ↓</a></div><div id="capacity" role="status">Reading host resources…</div><p id="status" role="status"></p><section id="boxes" class="hub-grid" aria-label="Boxes"></section>
<div class="forms"><details id="create" open><summary>Create a box</summary><form id="create-form">
<label>Name<input name="name" required maxlength="100" placeholder="Research box"></label><label>Agent<select name="agent"><option value="opencode">OpenCode</option><option value="claude">Claude</option><option value="codex">Codex</option></select></label><label>CPU cores<input name="cpu" type="number" min="0.05" step="0.05" required></label><label>RAM (MiB)<input name="memoryMiB" type="number" min="256" step="1" required></label><div id="opencode-settings"><label>Model configuration<select name="modelSource"><option value="profile">Saved provider / profile</option><option value="custom">Custom endpoint</option></select></label><div id="custom-model" hidden><label>Model endpoint<input name="modelURL" type="url" placeholder="http://model-host:8000/v1"></label><input name="model" type="hidden"><label class="check"><input name="vision" type="checkbox">Model supports images</label></div><p id="profile-hint" class="hint">Uses the selected profile’s model, provider configuration and API keys.</p></div><label>Model<input name="agentModel" maxlength="200"></label><p class="hint">Leave unchanged to keep the saved profile default. Choose a model or enter an exact ID.</p><label>Saved agent profile<select name="profile"><option value="">No profile</option></select></label><label>GitHub profile (optional)<select name="githubProfile"><option value="">No GitHub profile</option></select></label><label class="check"><input name="blender" type="checkbox">Blender 5 + MCP</label><label class="check"><input name="foundry" type="checkbox">Foundry</label><label>Proxy / IP<select name="proxy"><option value="">Direct</option><option value="tor-socks5">Tor SOCKS5</option><option value="cloudflare-warp">Cloudflare WARP</option></select></label><label>Initial goal (optional)<textarea name="goal" maxlength="100000"></textarea></label><button class="primary">Create / queue box</button></form></details>
<details><summary>Host budget</summary><p class="hint">All worker limits together must fit this budget. Reserve space separately for this host and its local model.</p><form id="policy-form"><label>Worker CPU budget<input name="cpus" type="number" min="0.05" step="0.05" required></label><label>Worker RAM budget (MiB)<input name="memoryMiB" type="number" min="256" required></label><label>Reserved host CPU<input name="reserveCPUs" type="number" min="0" step="0.05" required></label><label>Reserved host RAM (MiB)<input name="reserveMemoryMiB" type="number" min="256" required></label><label>Reserved local-model RAM (MiB)<input name="modelMemoryMiB" type="number" min="0" required></label><label>Minimum free Docker disk (MiB)<input name="minDiskFreeMiB" type="number" min="64" required></label><label>Maximum running boxes<input name="maxRunning" type="number" min="1" max="100" required></label><button>Save budget</button></form></details>
<details id="profiles"><summary>Saved profiles</summary><p class="hint">Upload configuration and login files from your computer. Only supported files are stored privately on this hub. Profiles can be reused across boxes.</p><div id="profile-list"></div><form id="profile-upload"><label>Profile name<input name="name" required maxlength="100"></label><label>Application<select name="agent"><option value="opencode">OpenCode</option><option value="claude">Claude</option><option value="codex">Codex</option><option value="github">GitHub CLI</option></select></label><p id="upload-help" class="hint"></p><label>Add configuration / login files<input name="files" type="file" multiple></label><div id="upload-files"></div><button class="primary">Upload profile</button><p id="upload-status" role="status"></p></form></details><details><summary>API guide</summary><p>Use <code>vbox hub token</code> on the hub host to retrieve your API token privately.</p><pre>GET /api/status
GET /api/profiles
POST /api/boxes
{"name":"research","cpu":0.5,"memoryMiB":1024,"goal":"Your goal"}

GET /api/boxes/BOX_ID
POST /api/boxes/BOX_ID/start
POST /api/boxes/BOX_ID/stop
POST /api/boxes/BOX_ID/delete
POST /api/boxes/BOX_ID/resources
{"cpu":0.5,"memoryMiB":1024}

GET /api/boxes/BOX_ID/messages
POST /api/boxes/BOX_ID/messages
Idempotency-Key: unique-message-id
{"text":"Your message"}

Authenticate with Authorization: Bearer $HUB_TOKEN.
Creation returns 202, including a box ID and workspace URL.
Poll its state; capacity limits may keep it queued.</pre></details></div><dialog id="resize"><form id="resize-form"><h2>Edit box resources</h2><input name="id" type="hidden"><label>CPU cores<input name="cpu" type="number" min="0.05" step="0.05" required></label><label>RAM (MiB)<input name="memoryMiB" type="number" min="256" required></label><p class="hint">Stop the box before lowering its RAM.</p><button class="primary">Apply</button> <button type="button" id="resize-cancel">Cancel</button></form></dialog></main>
<script>
const $=s=>document.querySelector(s),status=$('#status');let initialized=false,createKey=null,createBody=null,profiles=[],uploadFiles=new Map();const modelPicker=window.VMBoxModelPicker.create($('#create-form').elements.agentModel);let modelKey='';
async function api(path,options={}){const r=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});if(r.status===401){location.reload();throw Error('Sign in again')}if(!r.ok)throw Error(await r.text());return r.json()}
function element(tag,text,cls){const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n}
function render(boxes){const root=$('#boxes');root.replaceChildren();if(!boxes.length){root.append(element('p','Create your first box to get started.'));return}for(const b of boxes){const card=element('article','','hub-card');card.dataset.boxId=b.id;card.append(element('h2',b.spec.name),element('span',b.state,'state'),element('p',b.spec.cpu+' CPU · '+b.spec.memoryMiB+' MiB · '+b.spec.agent),element('p',b.reason||'','reason'),element('p',b.usage?'Using '+Math.round(b.usage.cpuPercent)+'% CPU · '+Math.round(b.usage.memoryMiB)+' MiB RAM':'Usage pending','hint'));const actions=element('div','','actions');if(b.state!=='deleted'){const open=element('a','Open chat');open.href=b.url;open.className='linkbtn';actions.append(open)}for(const action of ['start','stop','delete']){if(action==='start'&&b.desired==='running')continue;if(action==='stop'&&b.desired==='stopped')continue;const button=element('button',action[0].toUpperCase()+action.slice(1));button.onclick=async()=>{if(action==='delete'&&!confirm('Delete '+b.spec.name+' and its files permanently?'))return;button.disabled=true;try{await api('boxes/'+b.id+'/'+action,{method:'POST',body:'{}'});refresh()}catch(e){status.textContent=e.message;button.disabled=false}};actions.append(button)}const edit=element('button','Resources');edit.onclick=()=>{const f=$('#resize-form');f.elements.id.value=b.id;f.elements.cpu.value=b.spec.cpu;f.elements.memoryMiB.value=b.spec.memoryMiB;$('#resize').showModal()};actions.append(edit);card.append(actions);root.append(card)}}
async function refresh(){try{const [info,boxes]=await Promise.all([api('status'),api('boxes')]);$('#capacity').textContent=info.allocated.running+' / '+info.policy.maxRunning+' active · '+info.allocated.cpus+' / '+info.policy.cpus+' worker CPUs · '+info.allocated.memoryMiB+' / '+info.policy.memoryMiB+' MiB worker RAM · '+Math.round(info.host.availableMiB/1024)+' GiB host RAM available · '+Math.round(info.host.diskFreeMiB/1024)+' GiB disk free';render(boxes);if(!initialized){for(const [k,v] of Object.entries(info.policy)){const f=$('#policy-form').elements[k];if(f)f.value=v}const form=$('#create-form');for(const k of ['agent','cpu','memoryMiB','modelURL','model'])if(info.defaults[k]!==undefined)form.elements[k].value=info.defaults[k];form.elements.vision.checked=!!info.defaults.vision;initialized=true;modelKey='';configureAgent()}}catch(e){status.textContent=e.message}}
$('#create-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button.primary');b.disabled=true;try{const tools=[];for(const k of ['blender','foundry'])if(f.elements[k].checked)tools.push(k);if(f.elements.proxy.value)tools.push(f.elements.proxy.value);const spec={name:f.elements.name.value,agent:f.elements.agent.value,cpu:Number(f.elements.cpu.value),memoryMiB:Number(f.elements.memoryMiB.value),tools,profiles:[f.elements.profile.value,f.elements.githubProfile.value].filter(Boolean),goal:f.elements.goal.value,agentModel:f.elements.agentModel.value,agentReasoningEffort:f.elements.agentReasoningEffort.value};if(spec.agent==='opencode'){spec.modelSource=f.elements.modelSource.value;if(spec.modelSource==='custom'){spec.modelURL=f.elements.modelURL.value;spec.model=f.elements.agentModel.value||f.elements.model.value;spec.agentModel='';spec.agentReasoningEffort='';spec.vision=f.elements.vision.checked}}const payload=JSON.stringify(spec);if(createBody!==payload){createBody=payload;createKey=Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('')}await api('boxes',{method:'POST',headers:{'Idempotency-Key':createKey},body:payload});createKey=null;createBody=null;f.elements.name.value='';f.elements.goal.value='';status.textContent='Box queued';refresh()}catch(e){status.textContent=e.message}finally{b.disabled=false}};
$('#policy-form').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries([...new FormData(e.currentTarget)].map(([k,v])=>[k,Number(v)]));try{await api('policy',{method:'PUT',body:JSON.stringify(p)});status.textContent='Budget saved';refresh()}catch(e){status.textContent=e.message}};
$('#resize-cancel').onclick=()=>$('#resize').close();$('#resize-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{await api('boxes/'+f.elements.id.value+'/resources',{method:'POST',body:JSON.stringify({cpu:Number(f.elements.cpu.value),memoryMiB:Number(f.elements.memoryMiB.value)})});$('#resize').close();refresh()}catch(e){status.textContent=e.message}};
$('#hub-logout').onclick=async()=>{await fetch('/auth/logout',{method:'POST'});location.reload()};
function configureAgent(){const f=$('#create-form'),opencode=f.elements.agent.value==='opencode',custom=opencode&&f.elements.modelSource.value==='custom';$('#opencode-settings').hidden=!opencode;$('#custom-model').hidden=!custom;$('#profile-hint').hidden=custom;for(const k of ['modelURL','model','vision'])f.elements[k].disabled=!custom;f.elements.modelURL.required=custom;f.elements.model.required=custom;f.elements.profile.required=opencode&&!custom;const previous=f.elements.profile.value;f.elements.profile.replaceChildren(element('option',opencode&&!custom?'Select a profile':'No profile'));f.elements.profile.firstChild.value='';for(const p of profiles.filter(p=>p.agent===f.elements.agent.value)){const o=element('option',p.name);o.value=p.id;f.elements.profile.append(o)}if(profiles.some(p=>p.id===previous&&p.agent===f.elements.agent.value))f.elements.profile.value=previous;configureModel()}
async function refreshProfiles(selected){profiles=await api('profiles');const list=$('#profile-list');list.replaceChildren();if(!profiles.length)list.append(element('p','No saved profiles yet.','hint'));for(const p of profiles){const row=element('div','','profile-row'),remove=element('button','Delete');row.append(element('span',p.name+' · '+p.agent),remove);remove.type='button';remove.onclick=async()=>{if(!confirm('Delete saved profile '+p.name+'?'))return;try{await api('profiles/'+p.id,{method:'DELETE'});await refreshProfiles()}catch(e){$('#upload-status').textContent=e.message}};list.append(row)}const github=$('#create-form').elements.githubProfile,previousGitHub=github.value;github.replaceChildren(element('option','No GitHub profile'));github.firstChild.value='';for(const p of profiles.filter(p=>p.agent==='github')){const o=element('option',p.name);o.value=p.id;github.append(o)}if(profiles.some(p=>p.id===previousGitHub&&p.agent==='github'))github.value=previousGitHub;configureAgent();if(selected){const p=profiles.find(p=>p.id===selected);if(p?.agent==='github'){github.value=p.id}else if(p){$('#create-form').elements.agent.value=p.agent;configureAgent();$('#create-form').elements.profile.value=p.id}}}
function configureModel(){const f=$('#create-form'),agent=f.elements.agent.value,custom=agent==='opencode'&&f.elements.modelSource.value==='custom',profile=profiles.find(p=>p.id===f.elements.profile.value),key=[agent,custom,f.elements.profile.value,custom?f.elements.modelURL.value:''].join('|'),defaultModel=custom?f.elements.model.value:profile?.model||'';modelPicker.setApplication(custom?'custom':agent);if(key!==modelKey){modelKey=key;modelPicker.setValue(defaultModel);modelPicker.setReasoningEffort('')}modelPicker.setOptions(window.VMBoxModelPicker.optionsFor(custom?'':agent,[defaultModel].filter(Boolean)));modelPicker.setLoader(custom?()=>api('models?endpoint='+encodeURIComponent(f.elements.modelURL.value)):profile?async()=>{const catalog=await api('profiles/'+profile.id+'/models');return {...catalog,models:[...window.VMBoxModelPicker.optionsFor(agent,[]),...(catalog.models||[])]}}:null)}
$('#create-form').elements.agent.onchange=configureAgent;$('#create-form').elements.modelSource.onchange=configureAgent;$('#create-form').elements.profile.onchange=configureModel;$('#create-form').elements.modelURL.onchange=configureModel;
const supported={opencode:['opencode.json','opencode.jsonc','auth.json'],claude:['.credentials.json','settings.json','.claude.json'],codex:['auth.json','config.toml'],github:['hosts.yml']};
function uploadHelp(){const agent=$('#profile-upload').elements.agent.value;$('#upload-help').textContent={opencode:'Choose ~/.config/opencode/opencode.json (or .jsonc) and ~/.local/share/opencode/auth.json. Use Add files again for a different folder.',claude:'Choose ~/.claude/.credentials.json and settings.json; optionally ~/.claude.json. Show hidden files in the file picker if needed.',codex:'Choose auth.json and config.toml from the Codex home you want to save (for example ~/.codex-two).',github:'Choose ~/.config/gh/hosts.yml. For logins stored in your OS keyring, use vbox hub profile upload github=HOST:USER instead. Only active account credentials are copied.'}[agent]}
function renderUploadFiles(){const list=$('#upload-files');list.replaceChildren();for(const [name,file] of uploadFiles){const row=element('div','','profile-row'),remove=element('button','Remove');remove.type='button';remove.onclick=()=>{uploadFiles.delete(name);renderUploadFiles()};row.append(element('span',name+' · '+Math.ceil(file.size/1024)+' KiB'),remove);list.append(row)}}
$('#profile-upload').elements.agent.onchange=()=>{uploadFiles.clear();renderUploadFiles();uploadHelp()};
$('#profile-upload').elements.files.onchange=e=>{const agent=$('#profile-upload').elements.agent.value;for(const file of e.target.files){if(!supported[agent].includes(file.name)||file.size>512*1024){$('#upload-status').textContent='Choose supported configuration/login files, up to 512 KiB each.';continue}uploadFiles.set(file.name,file)}e.target.value='';renderUploadFiles()};
$('#profile-upload').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button.primary');b.disabled=true;try{if(!uploadFiles.size)throw Error('Choose configuration/login files first');const files={};for(const [name,file] of uploadFiles){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));files[name]=btoa(binary)}const profile=await api('profiles',{method:'POST',body:JSON.stringify({name:f.elements.name.value,agent:f.elements.agent.value,files})});uploadFiles.clear();renderUploadFiles();f.elements.name.value='';$('#upload-status').textContent='Profile uploaded';await refreshProfiles(profile.id)}catch(e){$('#upload-status').textContent=e.message}finally{b.disabled=false}};
uploadHelp();configureAgent();refreshProfiles().catch(e=>status.textContent=e.message);refresh();setInterval(refresh,3000);
</script>`
